def map_source_type(apps, schema_editor):
    StockTransaction = apps.get_model("inventory", "StockTransaction")
    mapping = {"TRANSFER": "TRANSFER", "RESERVATION": "RESERVATION", "PROJECT": "PROJECT", "BOM_REVISION": "BOM_REVISION"}
