def merge_duplicate_balances(apps, schema_editor):
    """Merge balance rows sharing the same identity (possible before the NULL-safe constraints).

    Balances are summed into the oldest row. Transactions reference component/warehouse/location,
    not the balance row, so no history is touched.
    """
    InventoryItem = apps.get_model("inventory", "InventoryItem")
    dupes = (
        InventoryItem.objects.values("component_id", "warehouse_id", "location_id", "lot_batch")
        .annotate(n=Count("id"))
        .filter(n__gt=1)
    )
    for d in dupes:
        rows = InventoryItem.objects.filter(
            component_id=d["component_id"], warehouse_id=d["warehouse_id"],
            location_id=d["location_id"], lot_batch=d["lot_batch"],
        ).order_by("id")
        totals = rows.aggregate(on_hand=Sum("quantity_on_hand"), reserved=Sum("quantity_reserved"))
        keep = rows.first()
        keep.quantity_on_hand = totals["on_hand"]
        keep.quantity_reserved = totals["reserved"]
        keep.save(update_fields=["quantity_on_hand", "quantity_reserved"])
        rows.exclude(pk=keep.pk).delete()


def backfill_reservations(apps, schema_editor):
    InventoryItem = apps.get_model("inventory", "InventoryItem")
    StockReservation = apps.get_model("inventory", "StockReservation")
    for res in StockReservation.objects.filter(inventory_item__isnull=True):
        item = InventoryItem.objects.filter(
            component_id=res.component_id, warehouse_id=res.warehouse_id, location_id=res.location_id, lot_batch=""
        ).first()
        if item is not None:
            res.inventory_item = item
            res.save(update_fields=["inventory_item"])


